function getSentineloneTranslation(key, lang) {
    return (sentineloneTranslations[lang] && sentineloneTranslations[lang][key]) ||
           (sentineloneTranslations.en && sentineloneTranslations.en[key]) || null;
}

function applySentineloneTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.sentinelone.") || key.startsWith("review.common."))) {
            const translation = getSentineloneTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} sentinelone translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applySentineloneTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applySentineloneTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applySentineloneTranslations(window.i18n?.getCurrentLanguage() || "en");
}
